head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil10606";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — resultDiv

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil10606.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_27", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "tr_28", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "tr_30", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "tr_32", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '1'); } }, { id: "c_when_36", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "tr_37", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "tr_39", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "tr_41", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '2'); } }, { id: "c_when_43", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "tr_44", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "tr_46", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "tr_48", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '3'); } }, { id: "c_when_50", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "tr_51", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "tr_53", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "tr_55", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '4'); } }, { id: "c_when_59", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "tr_60", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "tr_62", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "tr_64", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '5'); } }, { id: "c_when_66", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '6'); } }, { id: "tr_67", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '6'); } }, { id: "tr_71", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '6'); } }, { id: "tr_73", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '6'); } }, { id: "c_when_75", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '7'); } }, { id: "tr_76", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '7'); } }, { id: "tr_78", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '7'); } }, { id: "tr_80", fn: function(){ return ((dma_pageContext.get("resultDiv") ?? "") === '7'); } }, { id: "c_otherwise_82", fn: function(){ return (!(((dma_pageContext.get("resultDiv") ?? "") === '1') || ((dma_pageContext.get("resultDiv") ?? "") === '2') || ((dma_pageContext.get("resultDiv") ?? "") === '3') || ((dma_pageContext.get("resultDiv") ?? "") === '4') || ((dma_pageContext.get("resultDiv") ?? "") === '5') || ((dma_pageContext.get("resultDiv") ?? "") === '6') || ((dma_pageContext.get("resultDiv") ?? "") === '7'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("transMessage") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_ViewManualKeyWord_onclick
 * @description 「도움말」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_ViewManualKeyWord_onclick = function(e){
    try {
        fn_ViewManualKeyWord(0200000021)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil10606.btn_ViewManualKeyWord_onclick' }); }
};

/**
 * @method
 * @name btn_goList_onclick
 * @description btn_goList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goList_onclick = function(e){
    try {
        scwin.goList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil10606.btn_goList_onclick' }); }
};

/**
 * @method
 * @name btn_goList_2_onclick
 * @description btn_goList_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goList_2_onclick = function(e){
    try {
        scwin.goList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil10606.btn_goList_2_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {void}
 * @hidden N
 */
scwin.goList = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil10100/jldfil10100.xml');
};
